from pathlib import Path
import json,hashlib,shutil,datetime
R=Path(__file__).resolve().parents[1];Q=R/'round13'
load=lambda p:json.loads(p.read_text());dump=lambda p,x:p.write_text(json.dumps(x,indent=2,ensure_ascii=False),encoding='utf-8')
h=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert load(R/'round12/state/round_status.json')['status']=='COMPLETE';assert not Q.exists()
for d in ['tools','configs','inputs','graphs','rtl','src','build','results/hardware','state','logs','reports']:(Q/d).mkdir(parents=True,exist_ok=True)
sources=[(12,'sqrt20_odd_area','sqrt20_odd'),(12,'sqrt20_exact_area','sqrt20_exact'),(12,'sqrt24_exact_area','sqrt24_exact'),(10,'div10_odd','div10_odd'),(12,'mac9_add6_odd_native','mac9_add6_odd')]
cases=[];catalog=[];origins=[]
for rn,sn,n in sources:
 old=R/f'round{rn}';c=next(c for c in load(old/'configs/plan.json')['cases']if c['name']==sn);c=dict(c,name=n,source_round=rn,source_case=sn);cases.append(c)
 for suffix in ['', '_seed','_pairs']:
  p=old/f'graphs/{sn}{suffix}.json';d=Q/f'graphs/{n}{suffix}.json';shutil.copy2(p,d);origins.append(dict(source=str(p),target=str(d),sha256=h(p)))
 rec=load(old/f'results/{sn}_methods.json');dump(Q/f'inputs/{n}_original_methods.json',rec)
 for pi in range(len(rec)):
  p=old/f'results/{sn}_pair{pi}.csv';d=Q/f'results/{n}_pair{pi}.csv';shutil.copy2(p,d);origins.append(dict(source=str(p),target=str(d),sha256=h(p)))
 shutil.copy2(old/f'rtl/{sn}.xdc',Q/f'rtl/{n}.xdc')
 entries=load(old/'rtl/design_manifest.json');ppa={p['top']:p for p in load(old/'results/hardware/ppa.json')}
 for m in ['seed','numeric_window']:
  e=next(e for e in entries if e['case']==sn and e['method']==m);e0=next(x for x in entries if x['top']==(e['duplicate_of']or e['top']))
  assert not e0['inherited_physical'];rtl=old/f'rtl/{e0["top"]}.v';assert h(rtl)==e0['sha256']
  catalog.append(dict(case=n,source_case=sn,source_round=rn,method=m,canonical_sha256=e0['canonical_sha256'],rtl=str(rtl),rtl_file_sha256=h(rtl),physical_result=ppa[e0['top']]))
plan=dict(round=13,registered=datetime.datetime.now().astimezone().isoformat(),question='Can packing-aware relation completion preserve/create whole-network dual-output opportunities on the strongest observed inputs, avoiding the local-rewrite packing loss exposed by R12?',cases=cases,methods=['seed','numeric_window','packing_window'],baselines=['strongest observed input flow by case','unchanged numeric-window method'],innovations=['packing_window: generate relation-legal half tables while pricing whole-network packing opportunity, then select positive marginal-cost rewrites'],hypothesis='The same local support simplification can displace other legal pairs. Ranking candidate functions by their effect on the whole compatibility graph and charging lost matches should produce net physical savings on already compact mapped inputs.',source_policy='sqrt uses R12 area ABC, div uses R10 region ABC, MAC uses R12 native. Source selection is now fixed from completed evidence. No weaker-input substitution or ABC recipe search.',fixed_budget='Same source candidate pools and65536 proposal contexts as the copied completed rounds;8shared-pin sets,8retained topologies,top2 support completions,1024support masks,two2SAT orders. Proposed completion retains at most24 distinct functions per completed topology by the existing structural screen, then scores global packing; also scores the8 initial configs. No physical tool in search.',packing_model='Live support-reduced LUTs; explicit accepted LUT6_2 pairs reserved when both outputs survive; residual exact independent pairs are legal if union<=5, or union6 with a true six-input O6 whose zero-selector cofactor equals the <=5-input O5. Global maximum-cardinality matching with deterministic overlap tie scores; cyclic resource contractions removed conservatively. Constants/buffers are not counted as LUT sites. CARRY/FF are retained. This is a structural proxy, not a placement oracle.',selection='Choose one config per candidate using packed sites then live-output/edge/support tie criteria. Greedy marginal selection re-evaluates remaining non-overlapping candidates on the current graph; require strict lexicographic decrease in (predicted sites,live LUT outputs,edges), preserve union acyclicity, then unchanged one-pass full-domain error admission. Failed error admissions remain logged, no new search.',correctness='Full effective2^20/2^24 domains, same math WCE0/1; independent scalar and vendor HDL. Small hand-derived packing-oracle checks before running candidate search. No broad bug audit.',physical='15fixed models at unchanged clocks/boundaries/part/DSP0. Exact historical canonical matches may reuse results with SHA+clock checks and explicit source; newly generated configurations receive fresh simulation/physical jobs. No directive/clock sweep.',stop='Complete five cases and all three models before comparative analysis, score or next-round choice; preserve all negative results. No midpoint adaptation.',novelty_boundary='Packing costs and feedback exist in prior work. The candidate contribution is coupling allowed function/support generation to packing opportunity and displaced matches, not inventing matching or a dynamic area metric. This round alone is not SPFD-author-code reproduction or paper readiness.',score=dict(innovation=25,physical_gain=25,problem_coverage=20,correctness=20,cost=10))
dump(Q/'configs/plan.json',plan);dump(Q/'state/origins.json',origins);dump(Q/'state/physical_reuse_catalog.json',catalog);dump(Q/'state/engineering_repairs.json',[])
dump(Q/'state/input_hashes.json',{p.relative_to(Q).as_posix():h(p)for s in ['configs','inputs','graphs','results']for p in(Q/s).rglob('*')if p.is_file()})
dump(Q/'state/progress.json',dict(phase='REGISTERED_IMPLEMENTING_DRIVERS'))
c=load(R/'state/campaign.json');c.update(status='ROUND13_REGISTERED',active_round=13,root=str(Q),latest_progress='round13/state/progress.json');dump(R/'state/campaign.json',c)
(Q/'reports/REGISTERED_SCOPE_ZH.md').write_text('第13轮固定5个当前强输入、两个基线（输入流程及原主模型）和一个新候选packing_window。联合函数/支持生成考虑全网可打包机会及其损失，之后按整网边际代价选取修改。方法与预算详见configs/plan.json。全矩阵完成后分析；历史同字节物理结果按来源复用，不计成新跑。',encoding='utf-8')
print('Round13 registered:15models, five fixed strong inputs')
